Q: Circular buffer in JavaScript A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function createRingBuffer(length){

  let   pointer = 0;
  const buffer  = []; 

  return {
    get(key){return buffer[key];},
    push(item){
      buffer[pointer] = item;
      pointer = (length + pointer +1) % length;
    }
  };
};

const buf = createRingBuffer(3)
function log(){ console.log(`0: ${buf.get(0)}, 1: 0: ${buf.get(1)}, 2: ${buf.get(2)}`); }

buf.push(1);
buf.push(2);
buf.push(3);log()
buf.push(4);log()

buf.push(5);log()</code></pre>
</div>
</div>
</p>
<p>Update: in case you fill the buffer with numbers only, here are some one liner plugins:</p>
<pre><code>min  : function(){return Math.min.apply(Math, buffer);},
sum  : function(){return buffer.reduce(function(a, b){ return a + b; }, 0);},
</code></pre>
